APickupActor* UPickupInteractionComponent::GetClosestPickup() const
{
	// Resolve the actor to measure distance from. If our owner is a
	// Controller (no meaningful world location of its own, e.g. this
	// component lives on ADemoPlayerController rather than the pawn), fall
	// back to its possessed pawn.
	AActor* QueryOrigin = GetOwner();
	if (AController* OwnerController = Cast<AController>(QueryOrigin))
	{
		if (APawn* OwnerPawn = OwnerController->GetPawn())
		{
			QueryOrigin = OwnerPawn;
		}
	}
	if (!QueryOrigin)
	{
		return nullptr;
	}

	APickupActor* ClosestPickup = nullptr;
	float MinDistance = InteractionRadius;

	// Preferred path: live overlap tracking (populated when this component's
	// owner has a physical primitive root to overlap pickups with).
	for (APickupActor* Pickup : OverlappingPickups)
	{
		if (Pickup && Pickup->GetInteractionState() == EPickupActorState::Ready)
		{
			float Distance = UKismetMathLibrary::Vector_Distance(QueryOrigin->GetActorLocation(), Pickup->GetActorLocation());
			if (Distance < MinDistance)
			{
				MinDistance = Distance;
				ClosestPickup = Pickup;
			}
		}
	}
	if (ClosestPickup)
	{
		return ClosestPickup;
	}

	// Fallback path: direct world radius-query. Covers an owner with no
	// physical collision of its own (e.g. a PlayerController).
	UWorld* World = GetWorld();
	if (!World)
	{
		return nullptr;
	}

	for (TActorIterator<APickupActor> It(World); It; ++It)
	{
		APickupActor* Pickup = *It;
		if (!Pickup || Pickup->GetInteractionState() != EPickupActorState::Ready)
		{
			continue;
		}

		float Distance = UKismetMathLibrary::Vector_Distance(QueryOrigin->GetActorLocation(), Pickup->GetActorLocation());
		if (Distance < MinDistance)
		{
			MinDistance = Distance;
			ClosestPickup = Pickup;
		}
	}

	return ClosestPickup;
}

bool UPickupInteractionComponent::TryInteract()
{
	if (bIsHoldingItem)
	{
		// Already holding an item - drop it first before picking up another.
		return false;
	}

	APickupActor* ClosestPickup = GetClosestPickup();
	if (!ClosestPickup)
	{
		return false;
	}

	CurrentState = EPickupInteractionState::PickupInteracting;
	OnPickupInteract(ClosestPickup);

	// Capture the item's identity before PickUp() destroys the actor.
	HeldItemName = ClosestPickup->ItemName;
	bIsHoldingItem = true;
	OverlappingPickups.Remove(ClosestPickup);

	ClosestPickup->PickUp();

	CurrentState = EPickupInteractionState::PickupCompleted;
	OnPickupCompleted(ClosestPickup);

	return true;
}

bool UPickupInteractionComponent::TryDrop()
{
	if (!bIsHoldingItem)
	{
		return false;
	}

	AActor* OwnerActor = GetOwner();
	APawn* OwnerPawn = Cast<APawn>(OwnerActor);
	if (!OwnerPawn)
	{
		if (AController* OwnerController = Cast<AController>(OwnerActor))
		{
			OwnerPawn = OwnerController->GetPawn();
		}
	}

	UWorld* World = GetWorld();
	if (!OwnerPawn || !World)
	{
		return false;
	}

	const FVector DropLocation = OwnerPawn->GetActorLocation()
		+ OwnerPawn->GetActorForwardVector() * 150.0f
		+ FVector(0.0f, 0.0f, 20.0f);

	FActorSpawnParameters SpawnParams;
	SpawnParams.SpawnCollisionHandlingOverride = ESpawnActorCollisionHandlingMethod::AlwaysSpawn;

	ADropActor* Dropped = World->SpawnActor<ADropActor>(ADropActor::StaticClass(), DropLocation, OwnerPawn->GetActorRotation(), SpawnParams);
	if (Dropped)
	{
		Dropped->ItemName = HeldItemName;
	}

	bIsHoldingItem = false;
	HeldItemName = FText::GetEmpty();
	CurrentState = EPickupInteractionState::PickupReady;

	return Dropped != nullptr;
}
